// ❌ REST JSON (Heavy - 40 bytes)
{
  "id": 123,
  "name": "Alice",
  "isActive": true
}


// ✅ gRPC PROTOBUF (Lightweight - ~8 bytes)
// You define a strict 'contract' file.
syntax = "proto3";

message User {
  int32 id = 1;
  string name = 2;
  bool is_active = 3;
}

// The code automatically generates the classes for you in C#, Python, Go, etc!

// ❌ HTTP POLLING (The bad, old way to do real-time)
setInterval(async () => {
    // Spams the server every 1 second, even if there is no data.
    var messages = await fetch('/api/chat/latest'); 
}, 1000);


// ✅ SIGNALR / WEBSOCKETS (The modern way)
// Connect once, and just wait for the server to call YOU.
var connection = new signalR.HubConnectionBuilder()
    .withUrl("/chatHub")
    .build();

connection.on("ReceiveMessage", (user, message) => {
    console.log(`${user} says: ${message}`); // Happens instantly!
});

await connection.start();
